// INFO: shared by all site pages – language switch, theme toggle and the "pause animations" switch.
//       Each language has its own static page (/, /de/, /fr/ …, generated by tools/build-i18n.php).
//       The page language comes from the URL – no automatic redirects (crawler-friendly); thanks.html is the exception (see its <head>).
import { setLang, loadI18n, applyI18n, getTheme, setTheme, applyTheme, THEMES } from './app/js/i18n.js';

const root = document.documentElement.dataset.root || './';
const pageLang = document.documentElement.lang || 'en';
const page = location.pathname.split('/').pop() || '';
const sel = document.getElementById('langSel'), btn = document.getElementById('themeBtn'), motion = document.getElementById('motionBtn');
let t = (k) => k;

function paintTheme() {
  // INFO: the name says what a click does, the current mode follows (the icon alone shows only the state)
  const m = getTheme(), label = t('ui.theme_change', { mode: t('ui.theme_' + m) });
  btn.dataset.mode = m;
  btn.setAttribute('aria-label', label);
  btn.title = label;
}

function paintMotion() {
  if (!motion) return;
  const still = document.documentElement.classList.contains('still');
  motion.setAttribute('aria-pressed', String(still));
  motion.textContent = t(still ? 'ui.play_motion' : 'ui.pause_motion');
}

async function useLang(lang) {
  t = await loadI18n(root + 'i18n/', lang);
  applyI18n(t);
  sel.value = lang;
  const y = document.getElementById('y');
  if (y) y.textContent = new Date().getFullYear();
  paintTheme();
  paintMotion();
}

function goLang() {
  if (sel.value === pageLang) return;
  setLang(sel.value);
  location.href = root + (sel.value === 'en' ? '' : sel.value + '/') + (page === 'index.html' ? '' : page) + location.hash;
}

btn.addEventListener('click', () => { setTheme(THEMES[(THEMES.indexOf(getTheme()) + 1) % THEMES.length]); paintTheme(); });
// INFO: arrow keys on a closed <select> fire "change" per step (Windows, Firefox) – navigate only on Enter, blur or a pointer pick
let stepping = false;
sel.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') { e.preventDefault(); goLang(); } else stepping = /^(Arrow|Home|End|Page)/.test(e.key);
});
sel.addEventListener('pointerdown', () => { stepping = false; });
sel.addEventListener('change', () => { if (!stepping) goLang(); });
sel.addEventListener('blur', goLang);
// INFO: opening the app from a language page carries the language over
document.querySelectorAll('a[href$="app/"]').forEach((a) => a.addEventListener('click', () => setLang(pageLang)));
if (motion) {
  motion.addEventListener('click', () => {
    const still = document.documentElement.classList.toggle('still');
    document.querySelectorAll('svg').forEach((s) => { if (s.pauseAnimations) still ? s.pauseAnimations() : s.unpauseAnimations(); });
    paintMotion();
  });
}
applyTheme();
paintTheme();
useLang(pageLang);

// INFO: "Install News" – Chromium hands over its own install dialog (beforeinstallprompt, fires on / too although the app's scope is /app/).
//       Safari and Firefox have none, so the button opens the steps for the system instead; these start in the app, because
//       Safari adds the page it is on. Without JS, where no way exists (Firefox desktop) and inside the installed app, "Open News" stays alone.
const installBtns = document.querySelectorAll('[data-install]'), installDlg = document.getElementById('installDlg');
let installEvent = null, installWay = '';

function detectInstallWay() {
  const ua = navigator.userAgent;
  if (matchMedia('(display-mode: standalone)').matches || navigator.standalone) return '';
  if (/iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)) return 'ios';
  if (/Android/.test(ua) && /Firefox\//.test(ua)) return 'android';
  if ('onbeforeinstallprompt' in window) return 'chrome';
  if (/Macintosh/.test(ua) && /Version\/[\d.]+ Safari\//.test(ua)) return 'mac';
  return '';
}

function paintInstall() {
  installBtns.forEach((b) => {
    const on = !!installWay, link = b.parentElement.querySelector('[data-open-app]');
    b.hidden = !on;
    if (!link) return;
    link.classList.toggle('btn-primary', !on);
    link.classList.toggle('btn-ghost', on);
    link.querySelector('.l-app').hidden = on;
    link.querySelector('.l-browser').hidden = !on;
  });
}

if (installBtns.length && installDlg) {
  installWay = detectInstallWay();
  paintInstall();
  addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); installEvent = e; });
  addEventListener('appinstalled', () => { installEvent = null; installWay = ''; paintInstall(); if (installDlg.open) installDlg.close(); });
  let opener = null;
  installBtns.forEach((b) => b.addEventListener('click', () => {
    // INFO: read by track.js – which way the click took
    document.documentElement.dataset.installWay = installEvent ? 'prompt' : installWay;
    if (installEvent) {
      // INFO: the event can only prompt once – a later click after "cancel" shows the steps
      const ev = installEvent;
      installEvent = null;
      ev.prompt();
      return;
    }
    installDlg.querySelectorAll('ol[data-how]').forEach((ol) => { ol.hidden = ol.dataset.how !== installWay; });
    opener = b;
    installDlg.showModal();
  }));
  installDlg.addEventListener('close', () => opener?.focus());
}
